use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let c = Arc::new(Mutex::new(0));
    let hs: Vec<_> = (0..3).map(|_| {
        let c = Arc::clone(&c);
        thread::spawn(move || {
            let mut guard = ⟦slot1⟧;
            ⟦slot2⟧ += 1;
        })
    }).collect();
    for h in hs { h.join().unwrap(); }
    assert_eq!(*c.lock().unwrap(), 3);
}
